To solve this problem, you need to implement a **Global Tooltip Provider**.

Since Next.js components are isolated, you cannot rely on local state (like `useState` inside the component) to track which tooltip is open. Instead, you must lift the state up to a Context that wraps your entire application (or the specific section where these tooltips live).

Here is a complete, copy-pasteable solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to manage the global state of the tooltips.

**File:** `context/TooltipContext.tsx`

```tsx
'use client';

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of a tooltip
interface TooltipData {
  id: string;
  content: string;
  position: 'top' | 'bottom' | 'left' | 'right';
}

interface TooltipContextType {
  activeTooltip: TooltipData | null;
  openTooltip: (data: TooltipData) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeTooltip, setActiveTooltip] = useState<TooltipData | null>(null);

  const openTooltip = useCallback((data: TooltipData) => {
    // If a tooltip is already open, close it first (optional, but good for UX)
    setActiveTooltip(data);
  }, []);

  const closeTooltip = useCallback(() => {
    setActiveTooltip(null);
  }, []);

  return (
    <TooltipContext.Provider value={{ activeTooltip, openTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

